def _fit(X, y, it=25):
    n = len(y); A = np.column_stack([np.ones(n)] + ([X] if X is not None and X.size else []))
    b = np.zeros(A.shape[1])
    for _ in range(it):
        p = 1 / (1 + np.exp(-np.clip(A @ b, -30, 30))); w = p * (1 - p) + 1e-9
        H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
        step = np.linalg.solve(H, A.T @ (y - p)); b += step
        if np.abs(step).max() < 1e-7: break
    p = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
    return float(np.sum(y * np.log(p) + (1 - y) * np.log(1 - p)))

def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); ids = list(feats.ids); p = len(ids)
    labs = sorted(set(feats.stratum))
    S = np.column_stack([np.array([s == l for s in feats.stratum], float) for l in labs[1:]]) if len(labs) > 1 else np.zeros((len(y), 0))
    R = np.corrcoef(X.T); R = np.nan_to_num(R)
    def ll(cols, extra=None):
        M = [S] + [X[:, cols]] + ([extra] if extra is not None else [])
        return _fit(np.column_stack(M), y)
    def pv(l1, l0, df=1): return stats.chi2.sf(max(2 * (l1 - l0), 0), df)
    sel = []; gates = [0.25 / p, 0.05 / p, 0.02 / p]
    while len(sel) < MAX_DRIVERS:
        base = ll(sel); best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            l = ll(sel + [j])
            if best is None or l > best[1]: best = (j, l)
        if best is None or pv(best[1], base) > gates[min(len(sel), 2)]: break
        j = best[0]
        clus = [k for k in range(p) if abs(R[j, k]) >= 0.6 and k not in sel]
        if len(clus) > 1:
            lls = {k: ll(sel + [k]) for k in clus}; top = max(lls.values())
            cand = [k for k in clus if lls[k] >= top - 2]
            j = min(cand, key=lambda k: sum(max(ll(sel + [k, m]) - lls[k], 0) for m in clus if m != k))
        sel.append(j)
    changed = True
    while changed and len(sel) > 1:
        changed = False; full = ll(sel)
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if pv(full, ll(rest)) > 0.05 / p: sel = rest; changed = True; break
    # product / square screen
    base = ll(sel); r0 = y - y.mean(); pairs = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            z = X[:, a] * X[:, b]; z = z - z.mean(); sd = z.std()
            if sd < 1e-9: continue
            pairs.append((abs(z @ r0) / (sd * np.sqrt(len(y))), a, b))
    pairs.sort(reverse=True); npair = p * (p + 1) / 2; hits = []
    for _, a, b in pairs[:20]:
        mains = sorted(set(sel) | {a, b}); z = (X[:, a] * X[:, b])[:, None]
        l0 = ll(mains); l1 = ll(mains, z)
        if pv(l1, l0) < 0.005 / npair: hits.append((l1 - l0, a, b))
    hits.sort(reverse=True); prods = []
    for _, a, b in hits:
        if len(prods) < 2 and not any({a, b} & {c, d} for c, d in prods): prods.append((a, b))
    if prods:
        Z = np.column_stack([X[:, a] * X[:, b] for a, b in prods]); keep = []
        for j in sel:
            rest = [k for k in sel if k != j]
            if pv(ll(sel, Z), ll(rest, Z)) < 0.05 / p: keep.append(j)
        sel = keep
    drv = [ids[j] for j in sel]
    for a, b in prods:
        for k in (a, b):
            if ids[k] not in drv: drv.append(ids[k])
    drv = drv[:MAX_DRIVERS]
    return Design(drivers=tuple(drv), columns=tuple(ids[j] for j in sel),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

